def solve(data):
    packages = data['packages']
    roots = data['roots']
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def rows_for(name):
        rows = packages.get(name, [])
        if name in roots:
            low, high = roots[name]
            rows = [row for row in rows if low <= row['version'] <= high]
        return sorted(rows, key=lambda row: row['version'], reverse=True)

    def search(selected, pending):
        nonlocal best_vector, best_versions
        pending = pending - selected.keys()
        if not pending:
            vector = version_vector(names, selected)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row['version'] for name, row in selected.items()}
            return

        # An optimistic bound: every package not yet selected could take its
        # highest available version, whether or not it is ultimately reached.
        if best_vector is not None:
            upper = []
            for name in names:
                if name in selected:
                    upper.append(selected[name]['version'])
                else:
                    options = rows_for(name)
                    upper.append(max((row['version'] for row in options), default=-1))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        options = rows_for(name)
        for row in options:
            deps = row['deps']
            if any(dep not in packages for dep in deps):
                continue
            next_selected = dict(selected)
            next_selected[name] = row
            search(next_selected, (pending - {name}) | set(deps))

    search({}, set(roots))
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
